1	package com.example.starter.calibration.service;
2	
3	import java.time.Instant;
4	import java.util.ArrayList;
5	import java.util.HashSet;
6	import java.util.List;
7	import java.util.Set;
8	import java.util.UUID;
9	
10	import org.springframework.stereotype.Service;
11	import org.springframework.transaction.annotation.Transactional;
12	
13	import com.example.starter.calibration.api.ApiException;
14	import com.example.starter.calibration.api.BatchRejectedException;
15	import com.example.starter.calibration.api.ItemFailure;
16	import com.example.starter.calibration.api.dto.ReleaseResponse;
17	import com.example.starter.calibration.model.Certificate;
18	import com.example.starter.calibration.model.Measurement;
19	import com.example.starter.calibration.model.MeasurementStatus;
20	import com.example.starter.calibration.repo.CertificateRepository;
21	import com.example.starter.calibration.repo.MeasurementRepository;
22	import com.example.starter.calibration.repo.ReleaseRepository;
23	
24	/**
25	 * 批量放行服务：每批 1～50 条，整批原子生效；任一项不满足条件则整批拒绝（409）并返回各项原因。
26	 */
27	@Service
28	public class ReleaseService {
29	
30	    /** 单批最大条数。 */
31	    static final int MAX_BATCH_SIZE = 50;
32	
33	    private final MeasurementRepository measurements;
34	    private final CertificateRepository certificates;
35	    private final ReleaseRepository releases;
36	
37	    public ReleaseService(MeasurementRepository measurements,
38	                          CertificateRepository certificates,
39	                          ReleaseRepository releases) {
40	        this.measurements = measurements;
41	        this.certificates = certificates;
42	        this.releases = releases;
43	    }
44	
45	    /**
46	     * 原子批量放行。每条结果必须：处于待放行、判定合格、证书仍有效、放行人不同于提交人。
47	     * 行锁按测量键字典序获取，避免并发批次间死锁；证书行锁使撤销与放行按事务提交顺序生效。
48	     */
49	    @Transactional
50	    public ReleaseResponse release(List<String> keys, String actor) {
51	        String releaser = Inputs.requireText(actor, "X-Actor-Id");
52	        if (keys == null || keys.isEmpty() || keys.size() > MAX_BATCH_SIZE) {
53	            throw ApiException.badRequest("批量放行条数必须为 1～" + MAX_BATCH_SIZE);
54	        }
55	        List<String> orderedKeys = keys.stream().map(k -> Inputs.requireText(k, "keys[]")).toList();
56	        Set<String> distinct = new HashSet<>(orderedKeys);
57	        if (distinct.size() != orderedKeys.size()) {
58	            throw ApiException.badRequest("批量放行包含重复测量键");
59	        }
60	
61	        List<ItemFailure> failures = new ArrayList<>();
62	        List<Measurement> approved = new ArrayList<>();
63	        for (String key : orderedKeys.stream().sorted().toList()) {
64	            var locked = measurements.findByKeyForUpdate(key);
65	            if (locked.isEmpty()) {
66	                failures.add(new ItemFailure(key, List.of("MEASUREMENT_NOT_FOUND")));
67	                continue;
68	            }
69	            Measurement measurement = locked.get();
70	            List<String> reasons = new ArrayList<>();
71	            if (measurement.status() == MeasurementStatus.RELEASED) {
72	                reasons.add("ALREADY_RELEASED");
73	            } else if (measurement.status() != MeasurementStatus.PENDING) {
74	                reasons.add("NOT_PENDING");
75	            }
76	            if (!measurement.passed()) {
77	                reasons.add("NOT_PASSED");
78	            }
79	            Certificate cert = certificates.findByIdForUpdate(measurement.certificateId())
80	                    .orElseThrow(() -> ApiException.conflict("CERTIFICATE_MISSING",
81	                            "测量关联的证书不存在: " + measurement.certificateId()));
82	            if (cert.revoked()) {
83	                reasons.add("CERTIFICATE_REVOKED");
84	            }
85	            if (measurement.submittedBy().equals(releaser)) {
86	                reasons.add("SAME_ACTOR");
87	            }
88	            if (reasons.isEmpty()) {
89	                approved.add(measurement);
90	            } else {
91	                failures.add(new ItemFailure(key, reasons));
92	            }
93	        }
94	
95	        if (!failures.isEmpty()) {
96	            throw new BatchRejectedException(failures);
97	        }
98	
99	        String batchId = UUID.randomUUID().toString();
100	        Instant releasedAt = Instant.now();
101	        for (Measurement measurement : approved) {
102	            measurements.markReleased(measurement.id());
103	            releases.insert(batchId, measurement.id(), releaser, releasedAt);
104	        }
105	        return new ReleaseResponse(batchId, releaser, releasedAt, orderedKeys);
106	    }
107	}
